#include "components_registry.hpp"

#include <algorithm>

#include "all_components.hpp"      // generated by CMake from include/components/*.hpp

namespace
{
    template <StateIndicator L>
    class StateAdapter : public AnyState
    {
    public:
        StateAdapter(L line, std::size_t warmup) : line_(std::move(line)), warmup_(warmup) {}
        void update(const Bar& bar) override { line_.update(bar); }
        bool ready() const override { return line_.ready(); }
        int state() const override { return static_cast<int>(line_.state()); }
        std::size_t warmupBars() const override { return warmup_; }
        std::unique_ptr<AnyState> clone() const override { return std::make_unique<StateAdapter>(*this); }
    private:
        L line_;
        std::size_t warmup_;
    };

    template <GateIndicator L>
    class GateAdapter : public AnyGate
    {
    public:
        GateAdapter(L line, std::size_t warmup) : line_(std::move(line)), warmup_(warmup) {}
        void update(const Bar& bar) override { line_.update(bar); }
        bool ready() const override { return line_.ready(); }
        bool allows() const override { return static_cast<bool>(line_.allows()); }
        std::size_t warmupBars() const override { return warmup_; }
        std::unique_ptr<AnyGate> clone() const override { return std::make_unique<GateAdapter>(*this); }
    private:
        L line_;
        std::size_t warmup_;
    };

    template <typename S>
    ComponentInfo describe(const std::string& name)
    {
        ComponentInfo info;
        info.name = name;
        info.defaults = S::defaults();
        info.warmupBars = [](const Params& p) { return static_cast<std::size_t>(S::warmup(p)); };
        if constexpr (StateDefinition<S>)
        {
            info.kind = ComponentInfo::Kind::State;
            info.makeState = [](const Params& p) -> std::shared_ptr<AnyState>
            {
                return std::make_shared<StateAdapter<typename S::Line>>(S::make(p), S::warmup(p));
            };
        }
        else
        {
            static_assert(GateDefinition<S>, "a component must be a State or a Gate (see components.hpp)");
            info.kind = ComponentInfo::Kind::Gate;
            info.makeGate = [](const Params& p) -> std::shared_ptr<AnyGate>
            {
                return std::make_shared<GateAdapter<typename S::Line>>(S::make(p), S::warmup(p));
            };
        }
        return info;
    }

    std::vector<ComponentInfo> build()
    {
        std::vector<ComponentInfo> all;
        forEachComponent([&](const char* name, auto tag)
        {
            all.push_back(describe<typename decltype(tag)::type>(name));
        });
        std::sort(all.begin(), all.end(), [](const ComponentInfo& a, const ComponentInfo& b) { return a.name < b.name; });
        return all;
    }
}

const std::vector<ComponentInfo>& componentRegistry()
{
    static const std::vector<ComponentInfo> all = build();
    return all;
}

const ComponentInfo* findComponent(const std::string& name)
{
    for (const ComponentInfo& c : componentRegistry())
    {
        if (c.name == name)
            return &c;
    }
    return nullptr;
}

std::string componentNames()
{
    std::string out;
    for (const ComponentInfo& c : componentRegistry())
        out += (out.empty() ? "" : ", ") + c.name;
    return out;
}
